-- 📚 꼭집 주거 사전 — 전세임대 이자제 임대료 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 3.0초 · 결과:
-- {"anns": 4, "by_std": {"전세임대": 4}, "이자율": 4, "이자율_ex": ["2015122300019551", "2015122300019550", "2015122300019546"], "우대금리": 4, "우대금리_ex": ["2015122300019551", "2015122300019550", "2015122300019546"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where std='전세임대'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where std='전세임대' group by 1)q),'이자율',(select count(distinct announcement_id) from y where std='전세임대' and t~'(1\.2|1\.7|2\.2)\s*%'),'이자율_ex',(select json_agg(i) from(select distinct announcement_id i from y where std='전세임대' and t~'(1\.2|1\.7|2\.2)\s*%' order by 1 desc limit 3)q),'우대금리',(select count(distinct announcement_id) from y where std='전세임대' and t~'(0\.2|0\.3|0\.5)\s*%\s*p?'),'우대금리_ex',(select json_agg(i) from(select distinct announcement_id i from y where std='전세임대' and t~'(0\.2|0\.3|0\.5)\s*%\s*p?' order by 1 desc limit 3)q))j;
